     <script type="text/javascript">
         function attachCheckboxHandlers() {
            // get container
            var el = document.getElementById('BodyContent_ucRegistrationSubmit_FormerPublicOfficesHeldCL_pnlCheckBoxList');

            // get reference to input elements in container element
            var inputs = el.getElementsByTagName('input');

            // assign function to onclick property of each checkbox
            for (var i = 0; i < inputs.length; i++) {
                if (inputs[i].type === 'checkbox') {
                    inputs[i].onclick = onCheckedChange;

                    if (inputs[i].isDisabled == true) {
                        inputs[i].style.display = 'none';
                    }
                }
            }
        }

         function onCheckedChange(e) {

             if (document.getElementById('BodyContent_ucRegistrationSubmit_FormerPublicOfficesHeldCL_hfPageMode').value != "1") {
                 var el = document.getElementById('BodyContent_ucRegistrationSubmit_FormerPublicOfficesHeldCL_pnlCheckBoxList');
                 var inputs = el.getElementsByTagName('input');
                 var labels = el.getElementsByTagName('label');

                 var noneOfTheAbove = 'None of the above';
                 var noneOfTheAboveIndex;
                 var currentInputIndex;

                 for (var i = 0; i < labels.length; i++) {
                     if (labels[i].innerText == noneOfTheAbove) {
                         noneOfTheAboveIndex = i;
                         break;
                     }
                 }

                 for (var i = 0; i < inputs.length; i++) {
                     if (inputs[i].id == e.target.id) {
                         currentInputIndex = i;
                         break;
                     }
                 }

                 if (noneOfTheAboveIndex == currentInputIndex) {
                     if (e.target.checked) {
                         for (var i = 0; i < inputs.length; i++) {
                             if (i != noneOfTheAboveIndex)
                                 inputs[i].checked = false;
                         }
                     }
                 }
                 else if (noneOfTheAboveIndex != currentInputIndex) {
                     if (e.target.checked) {
                         inputs[noneOfTheAboveIndex].checked = false;
                     }

                     for (var i = currentInputIndex + 1; i < labels.length; i++) {
                         if (labels[i].innerText.indexOf('-') == 0)
                             inputs[i].checked = e.target.checked;
                         else
                             break;
                     }
                 }
             }
         }

        // call in script segment to register
        attachCheckboxHandlers();
    </script> 

